var FR_SENTENCE_COUNT = 1117;

// services/sentenceLibrary.ts
var asSentence = (items) => items;
var EN_SENTENCES_CAST = asSentence(EN_SENTENCES);
var ES_SENTENCES_CAST = asSentence(ES_SENTENCES);
var FR_SENTENCES_CAST = asSentence(FR_SENTENCES);
var LANG_CODES = {
  "English": "en",
  "Spanish": "es",
  "French": "fr"
};
function buildLibrary(lang, sentences, total) {
  const by_level = {};
  const by_topic = {};
  for (const s of sentences) {
    by_level[s.cefr_level] = (by_level[s.cefr_level] || 0) + 1;
    by_topic[s.topic] = (by_topic[s.topic] || 0) + 1;
  }
  return { language: lang, sentences, total_count: total, by_level, by_topic };
}
var EN_LIBRARY = buildLibrary("en", EN_SENTENCES_CAST, EN_SENTENCE_COUNT);
var ES_LIBRARY = buildLibrary("es", ES_SENTENCES_CAST, ES_SENTENCE_COUNT);
var FR_LIBRARY = buildLibrary("fr", FR_SENTENCES_CAST, FR_SENTENCE_COUNT);
function getSentenceLibrary(lang) {
  const code = LANG_CODES[lang] || "en";
  if (code === "en") return EN_LIBRARY;
  if (code === "es") return ES_LIBRARY;
  return FR_LIBRARY;
}
function pickDailySentence(library, level) {
  const targetLevel = level.charAt(0).toUpperCase() + level.slice(1);
  const levelMap = {
    "beginner": "A1",
    "elementary": "A2",
    "intermediate": "B1",
    "upper-intermediate": "B2",
    "advanced": "C1",
    "mastery": "C2"
  };
  const cefr = levelMap[level.toLowerCase()] || "B1";
  const candidates = library.sentences.filter((s) => s.cefr_level === cefr);
  if (candidates.length === 0) return library.sentences[Math.floor(Math.random() * library.sentences.length)];
  return candidates[Math.floor(Math.random() * candidates.length)];
}
function searchSentences(library, query) {
  const q = query.toLowerCase().trim();
  return library.sentences.filter(
    (s) => s.text.toLowerCase().includes(q) || s.topic.toLowerCase().includes(q) || s.tags.some((t) => t.toLowerCase().includes(q))
  ).slice(0, 50);
}

