// services/sanitization.ts
function safeLabel(value, maxLen = 60) {
  if (typeof value !== "string") return "";
  return value.replace(/[^\p{L}\p{N}\s\-']/gu, " ").replace(/\s+/g, " ").trim().slice(0, maxLen);
}
function safeSentence(value, maxLen = 500) {
  if (typeof value !== "string") return "";
  return value.replace(/[<>{}\\\`]/g, "").replace(/\s+/g, " ").trim().slice(0, maxLen);
}

// services/companionChatServer.ts
var generateCompanionReply = async (session, targetLanguage, level, openai2, transcribedAudio) => {
  const messagesText = session.messages.map(
    (m) => `${m.role === "user" ? "USER" : "COMPANION"}: ${m.text}${m.corrected_text ? `
(CORRECTION: ${m.corrected_text})` : ""}`
  ).join("\n---\n");
  const prompt = `
TARGET LANGUAGE: ${safeLabel(targetLanguage)}
LEARNER LEVEL: ${safeLabel(level)}

CONVERSATION HISTORY:
${messagesText}
${transcribedAudio ? `
TRANSCRIBED AUDIO: ${safeSentence(transcribedAudio, 500)}` : ""}

Generate the next companion reply.
`;
  const response = await openai2.chat.completions.create({
    model: "gpt-4o",
    messages: [{ role: "user", content: prompt }],
    response_format: { type: "json_object" },
    temperature: 0.7,
    max_tokens: 1024
  });
  return JSON.parse(response.choices[0].message.content);
};
var addCompanionMessage = (session, role, text, corrected_text, correction_note) => ({
  ...session,
  messages: [
    ...session.messages,
    {
      id: crypto.randomUUID(),
      role,
      text,
      corrected_text,
      correction_note,
      timestamp: Date.now()
    }
  ],
  last_active: Date.now()
});

